// Expanded Dasha-Bhukti Phala texts — Telugu
// Based on BPHS, Phaladeepika, Saravali

const Map<String, Map<String, String>> dashaBhuktiPhalasTeExpanded = {
  'ರವಿ': {
    'ರವಿ': 'రవి మహాదశలో రవి భుక్తి అధికారం, ప్రభుత్వ అనుకూలత మరియు నాయకత్వ లక్షణాలను అందిస్తుంది. వృత్తిలో ఉన్నతి, పై అధికారుల మెప్పు మరియు గుర్తింపు లభిస్తుంది. తలనొప్పి, జ్వరం, పిత్త దోషం మరియు కంటి సమస్యలు రావచ్చు. తండ్రితో సంబంధం మెరుగుపడుతుంది, కానీ అహంకారం పెరగవచ్చు.',
    'ಚಂದ್ರ': 'రవి-చంద్ర భుక్తిలో శత్రునాశం, మనశ్శాంతి మరియు కీర్తి లభిస్తుంది. తల్లి లేదా స్త్రీల నుండి లాభం, వస్త్ర-ఆభరణ ప్రాప్తి మరియు గృహ సుఖం కలుగుతుంది. ఆరోగ్యం సాధారణంగా బాగుంటుంది, కానీ శీత-కఫ దోషం రావచ్చు. కుటుంబంలో శాంతి మరియు సామరస్యం నెలకొంటుంది.',
    'ಕುಜ': 'రవి-కుజ భుక్తిలో ధైర్యం మరియు పరాక్రమం వృద్ధి చెందుతాయి. రోగ-వ్యాజ్యాల నిర్మూలన, అధికార లాభం మరియు పోటీలలో విజయం లభిస్తుంది. కానీ ఉష్ణ రోగం, రక్త సంబంధ సమస్య మరియు ప్రమాద భయం ఉంటుంది. సోదరులతో సంబంధం మిశ్రమంగా ఉంటుంది, భూమి-వాహన లాభం సాధ్యం.',
    'ರಾಹು': 'రవి-రాహు భుక్తిలో గ్రహణ దోషం వంటి అనుభవం కలుగుతుంది. ప్రభుత్వం లేదా పై అధికారుల నుండి భయం, స్థానచలనం మరియు మానసిక గందరగోళం ఏర్పడుతుంది. అనిరీక్షిత ఆరోగ్య సమస్య మరియు విష భయం ఉంటుంది. కుటుంబంలో అశాంతి, తండ్రికి కష్టం మరియు అపకీర్తి సాధ్యం.',
    'ಗುರು': 'రవి-గురు భుక్తిలో దైవానుగ్రహం, ధర్మ కార్యాలలో పురోగతి మరియు గురు కృప లభిస్తుంది. విద్యా-జ్ఞాన లాభం, ప్రభుత్వ గౌరవం మరియు సామాజిక హోదా పెరుగుతుంది. ఆరోగ్యం సాధారణంగా బాగుంటుంది, పిత్త దోషం తేలికగా ఉండవచ్చు. సంతాన సుఖం, తండ్రి ఆశీర్వాదం మరియు ఆధ్యాత్మిక అభివృద్ధి.',
    'ಶನಿ': 'రవి-శని భుక్తిలో అధికారులతో ఘర్షణ మరియు ప్రభుత్వ ఇబ్బంది ఏర్పడుతుంది. తండ్రి ఆరోగ్యం క్షీణించవచ్చు, ఆస్తి వివాదం మరియు స్థానమానం తగ్గే భయం. జ్వరం, ఎముకల-కీళ్ల నొప్పి మరియు శారీరక అలసట రావచ్చు. మానసిక ఒత్తిడి పెరిగి, ఓపిక అవసరం.',
    'ಬುಧ': 'రవి-బుధ భుక్తిలో బుద్ధిశక్తి మరియు వాక్చాతుర్యం మెరుగుపడతాయి. వ్యాపారంలో లాభం, రచన-విద్యా రంగంలో విజయం మరియు ప్రభుత్వ ఆమోదం లభించవచ్చు. చర్మ రోగం మరియు నాడీ బలహీనత సాధ్యం. మిత్రుల నుండి సహాయం లభిస్తుంది, సామాజిక హోదా పెరుగుతుంది.',
    'ಕೇತು': 'రవి-కేతు భుక్తిలో అనిరీక్షిత మార్పులు మరియు ఆధ్యాత్మిక జాగృతి ఏర్పడుతుంది. అధికార నష్టం, స్థానచలనం మరియు అపకీర్తి సాధ్యం. జ్వరం, తలనొప్పి మరియు శస్త్రచికిత్స భయం ఉంటుంది. ఆధ్యాత్మిక జ్ఞానం పెరుగుతుంది, కానీ లౌకిక కష్టాలు రావచ్చు.',
    'ಶುಕ್ರ': 'రవి-శుక్ర భుక్తిలో వస్త్ర-ఆభరణ-వాహన లాభం మరియు గృహ సుఖం లభిస్తుంది. కళా-వినోద రంగంలో ప్రభుత్వ గుర్తింపు సాధ్యం. కంటి సమస్య మరియు పిత్త దోషం రావచ్చు. దాంపత్య సుఖం, సామాజిక గౌరవం మరియు అందమైన వస్తువుల ప్రాప్తి.',
  },
  'ಚಂದ್ರ': {
    'ಚಂದ್ರ': 'చంద్ర మహాదశలో చంద్ర భుక్తి మనశ్శాంతి, కల్పనాశక్తి మరియు భావోద్వేగ సంతృప్తి అందిస్తుంది. ప్రజా సంబంధాలు, మీడియా మరియు ఆహార వ్యాపారంలో లాభం లభించవచ్చు. శీత-కఫం, జల సంబంధ రోగం మరియు మానసిక అశాంతి సాధ్యం. తల్లి సుఖం, గృహ సుఖం మరియు కుటుంబ సంబంధాలు మెరుగుపడతాయి.',
    'ಕುಜ': 'చంద్ర-కుజ భుక్తిలో భావోద్వేగాలు, కోపం మరియు గొడవలు సాధ్యం. భూమి-ఆస్తి లాభం ఉండవచ్చు, కానీ వ్యాజ్యాలు మరియు శత్రువుల ఇబ్బంది ఏర్పడుతుంది. రక్త సంబంధ రోగం, జ్వరం మరియు ప్రమాద భయం. సోదరులతో మనస్పర్ధ, కానీ ధైర్యం పెరుగుతుంది.',
    'ರಾಹು': 'చంద్ర-రాహు భుక్తిలో మానసిక గందరగోళం, భయం మరియు మాయ అనుభవం ఏర్పడుతుంది. ఆర్థిక ఎత్తుపల్లాలు, అనిరీక్షిత మార్పులు మరియు విదేశ సంబంధం సాధ్యం. మానసిక రోగం, నిద్రలేమి మరియు విష భయం ఉంటుంది. తల్లికి కష్టం, కుటుంబంలో అశాంతి.',
    'ಗುರು': 'చంద్ర-గురు భుక్తిలో గజకేసరి యోగం యొక్క మంచి ఫలం లభిస్తుంది. సంపద, మనశ్శాంతి, సామాజిక గౌరవం మరియు సంతాన సుఖం కలుగుతుంది. ఆరోగ్యం బాగుంటుంది, గురు కృపవల్ల అన్ని మేళ్ళు లభిస్తాయి. ధర్మ కార్యాలలో ఆసక్తి మరియు ఆధ్యాత్మిక అభివృద్ధి.',
    'ಶನಿ': 'చంద్ర-శని భుక్తిలో మానసిక ఒత్తిడి, చింత మరియు భావోద్వేగ కష్టాలు ఏర్పడతాయి. ఉద్యోగంలో ఆలస్యం, ఆర్థిక నష్టం మరియు సామాజిక అపకీర్తి సాధ్యం. వాత రోగం, కీళ్ల నొప్పి మరియు నిద్రలేమి. తల్లి ఆరోగ్యం క్షీణించవచ్చు, ఓపిక అవసరం.',
    'ಬುಧ': 'చంద్ర-బుధ భుక్తిలో కల్పనాశక్తి, రచన నైపుణ్యం మరియు వాక్చాతుర్యం పెరుగుతుంది. వ్యాపారంలో లాభం, విద్యా రంగంలో విజయం మరియు మీడియాలో గుర్తింపు. చర్మ రోగం, శీత-శ్వాస సమస్య సాధ్యం. మిత్ర-బంధు సహకారం మరియు సామాజిక జీవితంలో ఆనందం.',
    'ಕೇತು': 'చంద్ర-కేతు భుక్తిలో మానసిక గందరగోళం, భయం మరియు ఆధ్యాత్మిక జాగృతి ఏర్పడుతుంది. ఉద్యోగంలో లేదా వ్యాపారంలో అనిరీక్షిత మార్పులు సాధ్యం. నిద్రలేమి, మానసిక రోగం మరియు శస్త్రచికిత్స భయం. తల్లికి కష్టం, కానీ ధ్యాన-యోగంలో ఆసక్తి పెరుగుతుంది.',
    'ಶುಕ್ರ': 'చంద్ర-శుక్ర భుక్తిలో వస్త్ర-ఆభరణ-వాహన లాభం మరియు గృహ సుఖం లభిస్తుంది. కళా-సంగీత రంగంలో విజయం, అందమైన వస్తువుల ప్రాప్తి. కఫం పెరగవచ్చు, కానీ మొత్తం మీద ఆరోగ్యం బాగుంటుంది. దాంపత్య సుఖం, సామాజిక గౌరవం మరియు కుటుంబ ఆనందం.',
    'ರವಿ': 'చంద్ర-రవి భుక్తిలో ప్రభుత్వ అనుకూలత, కీర్తి మరియు అధికారం లభిస్తుంది. పదోన్నతి, తండ్రి ఆశీర్వాదం మరియు సామాజిక గుర్తింపు. పిత్త దోషం, కంటి సమస్య సాధ్యం. ఆత్మవిశ్వాసం పెరుగుతుంది, మనశ్శాంతి మరియు కుటుంబ సంబంధం మెరుగుపడుతుంది.',
  },
  'ಕುಜ': {
    'ಕುಜ': 'కుజ మహాదశలో కుజ భుక్తి ధైర్యం, పరాక్రమం మరియు పోరాట గుణాన్ని పెంచుతుంది. భూమి-ఆస్తి లాభం, పోటీ-వ్యాజ్యాలలో విజయం మరియు సైనిక-పోలీసు రంగంలో ఉన్నతి. రక్త రోగం, ప్రమాదం, ఎముక విరుగుడు మరియు శస్త్రచికిత్స సాధ్యం. సోదరులతో ఘర్షణ, కానీ శత్రువులను జయించే శక్తి లభిస్తుంది.',
    'ರಾಹು': 'కుజ-రాహు భుక్తిలో అంగారక దోషం మరియు అనిరీక్షిత ఆపదలు సాధ్యం. ప్రమాదం, వ్యాజ్యం, శత్రువుల కుట్ర మరియు మానసిక గందరగోళం ఏర్పడవచ్చు. రక్త రోగం, విష భయం మరియు శస్త్రచికిత్స భయం. కుటుంబంలో అశాంతి, సోదరులకు కష్టం.',
    'ಗುರು': 'కుజ-గురు భుక్తిలో భూమి-ఆస్తి లాభం, శత్రువులను జయించడం మరియు ధర్మ కార్యాలలో ఆసక్తి. గురు కృపవల్ల వ్యాజ్యాలలో విజయం, విద్యా లాభం మరియు సంతాన సుఖం. పిత్త దోషం తేలికగా ఉండవచ్చు, కానీ మొత్తం మీద ఆరోగ్యం బాగు. సామాజిక గౌరవం పెరుగుతుంది.',
    'ಶನಿ': 'కుజ-శని భుక్తిలో శత్రువుల ఇబ్బంది, వ్యాజ్యం మరియు ప్రమాద భయం ఉంటుంది. భూమి-ఆస్తి వివాదం, సోదరులతో ఘర్షణ మరియు అధికారులతో సమస్య. ఎముక విరుగుడు, రక్త రోగం మరియు శస్త్రచికిత్స సాధ్యం. కోపం నియంత్రించాలి, సంయమం అవసరం.',
    'ಬುಧ': 'కుజ-బుధ భుక్తిలో వాక్ వివాదం, వాదం మరియు న్యాయ సమస్య సాధ్యం. వ్యాపారంలో తొందరపాటు నిర్ణయాల వల్ల నష్టం రావచ్చు, కానీ సాంకేతిక రంగంలో విజయం. చర్మ రోగం, రక్త దోషం మరియు నాడీ బలహీనత. సోదరులతో మనస్పర్ధ, కానీ బుద్ధిశక్తి పెరుగుతుంది.',
    'ಕೇತು': 'కుజ-కేతు భుక్తిలో ప్రమాదం, శస్త్రచికిత్స మరియు అగ్ని భయం ఉంటుంది. శత్రువుల నుండి హాని, భూమి వివాదం మరియు వ్యాజ్యం సాధ్యం. రక్త దోషం, హఠాత్ గాయం మరియు ఆయుధ భయం. ఆధ్యాత్మిక జాగృతి మరియు సాహస ప్రవృత్తి పెరుగుతుంది.',
    'ಶುಕ್ರ': 'కుజ-శుక్ర భుక్తిలో భూమి-వాహన లాభం మరియు భోగ సుఖం లభిస్తుంది. కానీ దాంపత్యంలో కలహం, అతి కామ వాంఛ మరియు భావోద్వేగ ఘర్షణ సాధ్యం. జననేంద్రియ సమస్య, రక్త దోషం మరియు చర్మ రోగం. ఆస్తి వివాదం ఉండవచ్చు, పోటీలలో విజయం సాధ్యం.',
    'ರವಿ': 'కుజ-రవి భుక్తిలో ప్రభుత్వ అనుకూలత, అధికారం మరియు శత్రువులను జయించే శక్తి లభిస్తుంది. సైనిక-పోలీసు రంగంలో పదోన్నతి మరియు ప్రభుత్వ ఒప్పందం సాధ్యం. పిత్త దోషం, జ్వరం మరియు రక్తపోటు సాధ్యం. తండ్రి-కుమార సంబంధం మెరుగుపడుతుంది.',
    'ಚಂದ್ರ': 'కుజ-చంద్ర భుక్తిలో భావోద్వేగాలు మరియు ధైర్యం తగ్గడం సాధ్యం. భూమి-గృహ సంబంధ లాభం ఉండవచ్చు, కానీ మానసిక అశాంతి. రక్త రోగం, కఫం మరియు ఉదర సమస్య. తల్లితో సంబంధం మిశ్రమం, గృహ సుఖం పెరుగుతుంది.',
  },
  'ರಾಹು': {
    'ರಾಹು': 'రాహు మహాదశలో రాహు భుక్తి గందరగోళం, మాయ మరియు అనిరీక్షిత మార్పులను తెస్తుంది. విదేశ సంబంధం, సాంకేతిక రంగంలో లాభం కానీ మోసం-వంచన సాధ్యం. విష భయం, చర్మ రోగం మరియు మానసిక రోగం రావచ్చు. కుటుంబంలో అశాంతి, కానీ కొత్త అవకాశాలు ఏర్పడవచ్చు.',
    'ಗುರು': 'రాహు-గురు భుక్తిలో చాండాల యోగం ప్రభావం ఉంటుంది. ధర్మ విరోధం, గురు అవమానం కానీ విద్యా-జ్ఞాన లాభం సాధ్యం. కాలేయ సమస్య, ఉదర రోగం మరియు కొవ్వు పెరుగుదల. పిల్లలకు కష్టం, కానీ ఆధ్యాత్మిక జాగృతి ఏర్పడవచ్చు.',
    'ಶನಿ': 'రాహు-శని భుక్తిలో అత్యంత కఠిన సమయం, అనిరీక్షిత ఆపదలు ఏర్పడవచ్చు. ఉద్యోగంలో ఆలస్యం, ఆర్థిక నష్టం మరియు సామాజిక అపకీర్తి సాధ్యం. ఎముకల-కీళ్ల నొప్పి, చర్మ రోగం మరియు మానసిక ఒత్తిడి. కుటుంబంలో అశాంతి, ఓపిక అవసరం.',
    'ಬುಧ': 'రాహు-బుధ భుక్తిలో తెలివైన మోసం మరియు సంభాషణ గందరగోళం సాధ్యం. వ్యాపారంలో వంచన, విద్యలో ఆటంకం కానీ సాంకేతిక రంగంలో లాభం. నాడీ బలహీనత, చర్మ రోగం మరియు మానసిక అశాంతి. బంధువుల నుండి మోసం, కానీ కొత్త నేర్చుకునే అవకాశాలు.',
    'ಕೇತು': 'రాహు-కేతు భుక్తిలో అత్యంత కఠిన సమయం, మాయ-భ్రమ అనుభవం ఏర్పడుతుంది. ఉద్యోగంలో అస్థిరత, మోసం మరియు అపకీర్తి సాధ్యం. విష భయం, శస్త్రచికిత్స మరియు మానసిక రోగం. కుటుంబంలో అశాంతి, కానీ ఆధ్యాత్మిక అభివృద్ధికి అనుకూలం.',
    'ಶುಕ್ರ': 'రాహు-శుక్ర భుక్తిలో విదేశ సంబంధం, విలాస వస్తువుల లాభం మరియు కామ సుఖం లభిస్తుంది. భోగ-విలాసంలో అతిరేకం, మోసం మరియు అనైతిక సంబంధాల భయం. జననేంద్రియ రోగం, చర్మ సమస్య మరియు విష భయం. దాంపత్యంలో గందరగోళం, కానీ సంపద పెరగవచ్చు.',
    'ರವಿ': 'రాహు-రవి భుక్తిలో ప్రభుత్వం నుండి భయం, పదవి నష్టం మరియు అపకీర్తి సాధ్యం. తండ్రికి కష్టం, అధికారులతో ఘర్షణ మరియు స్థానచలనం. జ్వరం, తలనొప్పి మరియు అనిరీక్షిత రోగం రావచ్చు. కుటుంబంలో అశాంతి, కానీ సాంకేతిక రంగంలో అవకాశాలు.',
    'ಚಂದ್ರ': 'రాహు-చంద్ర భుక్తిలో మానసిక గందరగోళం, భయం మరియు కల్పనా ప్రపంచంలో జీవించడం సాధ్యం. తల్లి ఆరోగ్యం క్షీణించవచ్చు, గృహ సుఖం తగ్గుతుంది మరియు నిద్రలేమి. జల సంబంధ రోగం, మానసిక రోగం మరియు అలర్జీ. సామాజిక అపకీర్తి, కానీ సృజనాత్మక నైపుణ్యం పెరగవచ్చు.',
    'ಕುಜ': 'రాహు-కుజ భుక్తిలో ప్రమాదం, వ్యాజ్యం మరియు శత్రువుల కుట్ర సాధ్యం. భూమి-ఆస్తి వివాదం, రక్త రోగం మరియు శస్త్రచికిత్స భయం ఉంటుంది. కోపం పెరుగుతుంది, ఆయుధ-ప్రమాద భయం మరియు అగ్ని భయం. సోదరులకు కష్టం, కానీ ధైర్యం పెరుగుతుంది.',
  },
  'ಗುರು': {
    'ಗುರು': 'గురు మహాదశలో గురు భుక్తి జ్ఞానం, ధర్మం మరియు అన్ని మేళ్ళను అందిస్తుంది. విద్యా-పరిశోధన రంగంలో ఉన్నతి, సామాజిక గౌరవం మరియు గురు కృప లభిస్తుంది. ఆరోగ్యం బాగుంటుంది, కొవ్వు-కాలేయ సమస్య తేలికగా సాధ్యం. సంతాన సుఖం, ధర్మ కార్యాలలో ఆసక్తి మరియు ఆధ్యాత్మిక అభివృద్ధి.',
    'ಶನಿ': 'గురు-శని భుక్తిలో ధర్మ-కర్మ సమతుల్యత మరియు కఠిన పరిశ్రమ ఫలం లభిస్తుంది. విద్యా-ఉద్యోగంలో ఆలస్యం కానీ స్థిరమైన పురోగతి సాధ్యం. వాత రోగం, కీళ్ల నొప్పి మరియు కొవ్వు పెరుగుదల. పెద్దల ఆరోగ్యం క్షీణించవచ్చు, ఓపిక అవసరం.',
    'ಬುಧ': 'గురు-బుధ భుక్తిలో విద్యా-జ్ఞాన లాభం మరియు రచన-పరిశోధనలో విజయం లభిస్తుంది. వ్యాపార-విద్యా రంగంలో ఉన్నతి, గురు కృప మరియు బుద్ధిశక్తి మెరుగుపడుతుంది. ఆరోగ్యం సాధారణంగా బాగుంటుంది, చర్మ సమస్య సాధ్యం. పిల్లలకు విద్యా లాభం, సామాజిక గౌరవం పెరుగుతుంది.',
    'ಕೇತು': 'గురు-కేతు భుక్తిలో ఆధ్యాత్మిక జ్ఞానం పెరుగుతుంది, కానీ లౌకిక ఆటంకాలు రావచ్చు. ధర్మ-కర్మ సమస్య, పిల్లలకు కష్టం మరియు అనిరీక్షిత మార్పులు. కొవ్వు-కాలేయ సమస్య, శస్త్రచికిత్స సాధ్యం. మోక్ష మార్గ ఆసక్తి, ధ్యాన-యోగంలో ఆసక్తి.',
    'ಶುಕ್ರ': 'గురు-శుక్ర భుక్తిలో వస్త్ర-ఆభరణ-వాహన లాభం మరియు దాంపత్య సుఖం లభిస్తుంది. వివాహ యోగం, కళా రంగంలో విజయం మరియు సంగీతంలో ఆసక్తి పెరుగుతుంది. కఫ-పిత్త దోషం మరియు ఉదర సమస్య సాధ్యం. సామాజిక గౌరవం మరియు సంపద పెరుగుతుంది.',
    'ರವಿ': 'గురు-రవి భుక్తిలో శివాలయ దర్శనం, రాజకీయ లాభం మరియు ఆరోగ్య అభివృద్ధి లభిస్తుంది. తండ్రి నుండి ఆస్తి, ప్రభుత్వ గౌరవం మరియు నాయకత్వ అవకాశం. ధార్మిక కార్యాలలో ఆసక్తి మరియు గురు-పెద్దల ఆశీర్వాదం. ఆత్మవిశ్వాసం మరియు కీర్తి పెరుగుతుంది.',
    'ಚಂದ್ರ': 'గురు-చంద్ర భుక్తిలో గజకేసరి యోగం యొక్క అద్భుత ఫలం లభిస్తుంది. అఖండ సంపద, మనశ్శాంతి, గృహ-వాహన సుఖం మరియు సామాజిక గౌరవం. తల్లి సుఖం, సృజనాత్మక పనులలో విజయం మరియు ఆరోగ్యం బాగు. వివాహ యోగం మరియు సంతాన లాభం.',
    'ಕುಜ': 'గురు-కుజ భుక్తిలో భూ లాభం, శత్రువులపై విజయం మరియు అసాధారణ ధైర్యం లభిస్తుంది. ఆస్తి వృద్ధి, వాహన లాభం మరియు పోటీలలో విజయం సాధ్యం. ఉష్ణ రోగం, పిత్త దోషం మరియు కోపం పెరగవచ్చు. ధార్మిక యజ్ఞ కార్యాలలో ఆసక్తి.',
    'ರಾಹು': 'గురు-రాహు భుక్తిలో చాండాల యోగం ప్రభావం కనిపిస్తుంది. బంధు-మిత్రుల వ్యతిరేకత, ధర్మ భ్రష్టత మరియు మానసిక గందరగోళం ఏర్పడవచ్చు. ఉదర-కాలేయ రోగం, అనిరీక్షిత ఖర్చు మరియు అపకీర్తి సాధ్యం. గురు-పెద్దలతో అభిప్రాయ భేదం.',
  },
  'ಶನಿ': {
    'ಶನಿ': 'శని మహాదశలో శని భుక్తి కఠిన పరిశ్రమ మరియు ఆలస్య అనుభవాన్ని ఇస్తుంది. ఉద్యోగంలో స్థిరత రావచ్చు, కానీ పురోగతి నెమ్మదిగా ఉంటుంది. ఎముకల-కీళ్ల నొప్పి, వాత రోగం మరియు శారీరక అలసట రావచ్చు. కుటుంబంలో పెద్దల ఆరోగ్యం క్షీణించవచ్చు, ఒంటరితనం అనుభవం సాధ్యం.',
    'ಬುಧ': 'శని-బుధ భుక్తిలో బుద్ధిశక్తితో కష్టాలను అధిగమించే సామర్థ్యం వస్తుంది. వ్యాపారంలో మెరుగుదల, లెక్కల-బాధ్యతల పనులలో లాభం మరియు విద్యా రంగంలో పురోగతి. చర్మ రోగం, నాడీ బలహీనత మరియు శ్వాస సమస్య సాధ్యం. బంధువుల సహాయం లభించవచ్చు, వివాదాలలో జాగ్రత్త అవసరం.',
    'ಕೇತು': 'శని-కేతు భుక్తిలో అనిరీక్షిత కష్టాలు మరియు ఆధ్యాత్మిక ఆసక్తి ఏర్పడుతుంది. ఉద్యోగంలో అస్థిరత, హఠాత్ నష్టం మరియు స్థానచలనం సాధ్యం. కాలు-పాద నొప్పి, అస్పష్ట రోగం మరియు శస్త్రచికిత్స భయం. పూర్వజన్మ కర్మఫల అనుభవం, ధ్యాన-సాధనలో ఆసక్తి.',
    'ಶುಕ್ರ': 'శని-శుక్ర భుక్తిలో భోగ సుఖం మరియు సంపద లాభం సాధ్యం. వాహన-భూమి యోగం, కళా రంగంలో విజయం మరియు వివాహ సంబంధ శుభ సంఘటనలు. జననేంద్రియ సమస్య, మధుమేహం మరియు కంటి ఇబ్బంది సాధ్యం. దాంపత్యంలో మిశ్రమ ఫలం, భాగస్వామి ఆరోగ్యంపై జాగ్రత్త అవసరం.',
    'ರವಿ': 'శని-రవి భుక్తిలో అధికారులతో ఘర్షణ మరియు ప్రభుత్వ ఇబ్బంది ఏర్పడుతుంది. తండ్రి ఆరోగ్యం క్షీణించవచ్చు, ఆస్తి వివాదం మరియు పదవి నష్ట భయం. జ్వరం-ఉష్ణ రోగం, హృదయ సమస్య మరియు శారీరక అలసట. ధైర్యం-ఆత్మవిశ్వాసం తగ్గి మానసిక ఒత్తిడి పెరుగుతుంది.',
    'ಚಂದ್ರ': 'శని-చంద్ర భుక్తిలో మానసిక అశాంతి మరియు భావోద్వేగ కష్టాలు ఏర్పడతాయి. తల్లి ఆరోగ్యం క్షీణించవచ్చు, గృహ సుఖం తగ్గుతుంది మరియు సామాజిక అపకీర్తి. కఫ-వాత దోషం, జల సంబంధ రోగం మరియు నిద్రలేమి. దైనందిన జీవితంలో ఆటంకాలు, కానీ సహనంతో గెలవచ్చు.',
    'ಕುಜ': 'శని-కుజ భుక్తిలో శత్రువుల ఇబ్బంది, వ్యాజ్యం మరియు ప్రమాద భయం ఉంటుంది. భూమి-ఆస్తి వివాదం, సోదరులతో మనస్పర్ధ మరియు శత్రువులపై ఓటమి సాధ్యం. రక్త దోషం, ఎముక విరుగుడు మరియు శస్త్రచికిత్స అవసరం రావచ్చు. క్రోధ నియంత్రణ మరియు సంయమం అవసరం.',
    'ರಾಹು': 'శని-రాహు భుక్తిలో అత్యంత కఠిన సమయం అనుభవమవచ్చు. అనిరీక్షిత ఆపత్తులు, మోసం, విదేశ ప్రయాణం మరియు స్థాన భ్రష్టత సాధ్యం. అస్పష్ట రోగం, విష భయం మరియు మానసిక నిరాశ. కుటుంబంలో అశాంతి, దొంగల భయం మరియు నిందా.',
    'ಗುರು': 'శని-గురు భుక్తిలో ధార్మిక కార్యాలలో ఆసక్తి మరియు గురు కృప లభిస్తుంది. విద్యా లాభం, సంతాన సుఖం మరియు ధర్మ-కర్మలలో పురోగతి. ఆరోగ్యం మెరుగుపడుతుంది, కానీ కొవ్వు పెరుగుదల మరియు కాలేయ సమస్య సాధ్యం. సామాజిక గౌరవం పెరుగుతుంది మరియు సత్కర్మల ఫలం లభిస్తుంది.',
  },
  'ಬುಧ': {
    'ಬುಧ': 'బుధ మహాదశలో బుధ భుక్తి బుద్ధిశక్తి మరియు వాక్చాతుర్య వృద్ధిని ఇస్తుంది. వ్యాపార-వాణిజ్యంలో లాభం, విద్యా రంగంలో విజయం మరియు రచన-సంభాషణ పనులలో పురోగతి. చర్మ రోగం, నాడీ బలహీనత మరియు శ్వాస సమస్య సాధ్యం. మిత్ర-బంధు సహకారం, విద్యార్థులకు శుభఫలం.',
    'ಕೇತು': 'బుధ-కేతు భుక్తిలో బుద్ధి భ్రమణ, గందరగోళం మరియు తప్పు నిర్ణయాలు సాధ్యం. వ్యాపారంలో మోసం, విద్యలో ఆటంకం మరియు అనిరీక్షిత నష్టం. చర్మ-నాడీ రోగం, అస్పష్ట వ్యాధి మరియు మానసిక చంచలత్వం. ఆధ్యాత్మిక చింతన వైపు ఆసక్తి పెరగవచ్చు.',
    'ಶುಕ್ರ': 'బుధ-శుక్ర భుక్తిలో కళా-సాహిత్య-సంగీతంలో విజయం మరియు భోగ సుఖం లభిస్తుంది. వ్యాపారంలో మంచి లాభం, వస్త్ర-ఆభరణ ప్రాప్తి మరియు వివాహ యోగం. ఆరోగ్యం సాధారణంగా బాగుంటుంది, అతి భోగం వల్ల కఫ వృద్ధి సాధ్యం. దాంపత్య సుఖం మరియు సామాజిక గౌరవం పెరుగుతుంది.',
    'ರವಿ': 'బుధ-రవి భుక్తిలో ప్రభుత్వ అనుకూలత, అధికార స్థానం మరియు వృత్తి ఉన్నతి లభిస్తుంది. వ్యాపారంలో ప్రభుత్వ ఒప్పందం, పదోన్నతి మరియు నాయకత్వ అవకాశం. తలనొప్పి, కంటి సమస్య మరియు పిత్త దోషం సాధ్యం. తండ్రితో మంచి సంబంధం మరియు బౌద్ధిక సాధన.',
    'ಚಂದ್ರ': 'బుధ-చంద్ర భుక్తిలో కల్పనాశక్తి, సృజనాత్మకత మరియు సంభాషణ నైపుణ్యం పెరుగుతుంది. వ్యాపారంలో ప్రజా సంబంధ లాభం, రచన-మీడియా రంగంలో విజయం. కఫ-శీత రోగం మరియు మనస్సు చంచలత్వం సాధ్యం. తల్లితో మంచి సంబంధం, గృహ సుఖం మరియు భావోద్వేగ స్థిరత.',
    'ಕುಜ': 'బుధ-కుజ భుక్తిలో వాక్ వివాదం, వాదం మరియు న్యాయ సమస్య సాధ్యం. వ్యాపారంలో తొందరపాటు నిర్ణయాల వల్ల నష్టం రావచ్చు. చర్మ రోగం, రక్త దోషం మరియు నాడీ బలహీనత. సోదరులతో మనస్పర్ధ, కానీ ధైర్య-పరాక్రమం పెరుగుతుంది.',
    'ರಾಹು': 'బుధ-రాహు భుక్తిలో మానసిక గందరగోళం, మోసం మరియు నమ్మకద్రోహం అనుభవమవచ్చు. వ్యాపారంలో దొంగతనం, విద్యలో ఆటంకం మరియు సంభాషణలో తప్పు అవగాహన. నాడీ బలహీనత, చర్మ రోగం మరియు విష భయం సాధ్యం. బంధువుల నుండి మోసం మరియు అపకీర్తి సాధ్యం.',
    'ಗುರು': 'బుధ-గురు భుక్తిలో విద్యా-జ్ఞాన లాభం మరియు ధార్మిక కార్యాలలో పురోగతి కనబడుతుంది. విద్యా రంగంలో ఉన్నత స్థానం, గురు కృప మరియు ధార్మిక యాత్ర సాధ్యం. ఆరోగ్యం సాధారణంగా బాగుంటుంది, కొవ్వు వృద్ధి సాధ్యం. సంతాన సుఖం, సామాజిక గౌరవం మరియు బౌద్ధిక పురోగతి.',
    'ಶನಿ': 'బుధ-శని భుక్తిలో వ్యాపారంలో ఆలస్యం మరియు కఠిన పరిశ్రమ అవసరం ఏర్పడుతుంది. విద్యలో ఆటంకం, సంభాషణలో ఇబ్బంది మరియు నిర్ణయం తీసుకోవడంలో ఆలస్యం. వాత రోగం, ఎముక నొప్పి మరియు నాడీ సమస్య సాధ్యం. బంధువుల నుండి దూరం, ఒంటరితనం అనుభవం.',
  },
  'ಕೇತು': {
    'ಕೇತು': 'కేతు మహాదశలో కేతు భుక్తి ఆధ్యాత్మిక జాగృతి మరియు లౌకిక విరక్తిని ఇస్తుంది. అనిరీక్షిత సంఘటనలు, హఠాత్ మార్పులు మరియు పూర్వజన్మ కర్మఫల అనుభవం. అస్పష్ట రోగం, శస్త్రచికిత్స భయం మరియు ప్రమాద భయం. కుటుంబం నుండి దూరం, ధ్యాన-యోగంలో ఆకర్షణ మరియు మోక్ష మార్గ అన్వేషణ.',
    'ಶುಕ್ರ': 'కేతు-శుక్ర భుక్తిలో భోగ-వైరాగ్య ఘర్షణ అనుభవమవుతుంది. వాహన-వస్త్ర లాభం సాధ్యం కానీ దాంపత్యంలో అశాంతి మరియు భావోద్వేగ గందరగోళం. జననేంద్రియ సమస్య, చర్మ రోగం మరియు అలర్జీ సాధ్యం. కళా రంగంలో అనిరీక్షిత విజయం లేదా ఓటమి.',
    'ರವಿ': 'కేతు-రవి భుక్తిలో అధికార నష్టం, ప్రభుత్వ ఇబ్బంది మరియు తండ్రికి కష్టం రావచ్చు. ఉద్యోగంలో అనిశ్చితత, స్థానచలనం మరియు అపకీర్తి సాధ్యం. జ్వరం, ఉష్ణ రోగం మరియు అస్పష్ట శిరోవేదన. ఆధ్యాత్మిక జ్ఞానోదయం మరియు సాధన మార్గం తెరవబడవచ్చు.',
    'ಚಂದ್ರ': 'కేతు-చంద్ర భుక్తిలో మానసిక అశాంతి, భ్రమ మరియు భావోద్వేగ అస్థిరత ఏర్పడుతుంది. తల్లి ఆరోగ్యం క్షీణించవచ్చు, గృహ సుఖం తగ్గుతుంది మరియు నిద్రా సమస్య. జల సంబంధ రోగం, మానసిక ఒత్తిడి మరియు అంతర్ముఖత్వం. ధ్యాన-యోగంలో ఆసక్తి పెరిగి ఆధ్యాత్మిక అభివృద్ధి సాధ్యం.',
    'ಕುಜ': 'కేతు-కుజ భుక్తిలో ప్రమాదం, శస్త్రచికిత్స మరియు అగ్ని భయం ఉంటుంది. శత్రువుల నుండి హాని, భూమి వివాదం మరియు వ్యాజ్యం సాధ్యం. రక్త దోషం, హఠాత్ గాయం మరియు ఆయుధ భయం. సోదరులకు కష్టం, కానీ ధైర్యం మరియు సాహస ప్రవృత్తి పెరుగుతుంది.',
    'ರಾಹು': 'కేతు-రాహు భుక్తిలో అత్యంత కఠిన సమయం, మాయ-భ్రమ అనుభవం ఏర్పడుతుంది. ఉద్యోగంలో అస్థిరత, మోసం మరియు అపకీర్తి సాధ్యం. విష భయం, అస్పష్ట రోగం మరియు మానసిక నిరాశ. కుటుంబంలో అశాంతి, కానీ ఆధ్యాత్మిక అభివృద్ధికి అనుకూలం.',
    'ಗುರು': 'కేతు-గురు భుక్తిలో ఆధ్యాత్మిక జ్ఞాన వృద్ధి మరియు గురు కృప లభిస్తుంది. ధార్మిక యాత్ర, తీర్థ క్షేత్ర సందర్శనం మరియు సత్సంగ యోగం. ఆరోగ్యం మెరుగుపడుతుంది, మోక్ష మార్గ ఆసక్తి పెరుగుతుంది. సంతాన సుఖం మరియు విద్యా లాభం సాధ్యం.',
    'ಶನಿ': 'కేతు-శని భుక్తిలో అతి కఠిన సమయం, శారీరక-మానసిక కష్టాలు అనుభవమవుతాయి. ఉద్యోగంలో స్థాన నష్టం, ఆర్థిక ఆటంకం మరియు పెద్దల అసహకారం. ఎముకల-కీళ్ల నొప్పి, కాలు నొప్పి మరియు అస్పష్ట రోగం. వైరాగ్య భావన పెరిగి, సన్యాసం లేదా ఏకాంత వాసం వైపు ఆసక్తి.',
    'ಬುಧ': 'కేతు-బుధ భుక్తిలో బుద్ధి గందరగోళం, సంభాషణ సమస్య మరియు తప్పు అవగాహన సాధ్యం. వ్యాపారంలో మోసం, విద్యలో ఆటంకం మరియు లెక్కల సమస్య. నాడీ రోగం, చర్మ సమస్య మరియు శ్వాస ఇబ్బంది. ఆధ్యాత్మిక సాహిత్య-అధ్యయనంలో ఆసక్తి పెరగవచ్చు.',
  },
  'ಶುಕ್ರ': {
    'ಶುಕ್ರ': 'శుక్ర మహాదశలో శుక్ర భుక్తి అపార భోగ-సుఖం, సంపద మరియు వైభవాన్ని ఇస్తుంది. వాహన-భూమి-ఆభరణ లాభం, కళా రంగంలో విజయం మరియు వివాహ సంబంధ శుభ సంఘటనలు. ఆరోగ్యం సాధారణంగా బాగుంటుంది, అతి భోగం వల్ల మధుమేహం మరియు కఫ రోగం సాధ్యం. దాంపత్య సుఖం అపారం, సామాజిక ప్రతిష్ఠ పెరుగుతుంది.',
    'ರವಿ': 'శుక్ర-రవి భుక్తిలో ప్రభుత్వ అనుకూలత, అధికారం మరియు కీర్తి లభిస్తుంది. కళా-వినోద రంగంలో ప్రభుత్వ గుర్తింపు మరియు పురస్కారం సాధ్యం. పిత్త-ఉష్ణ రోగం మరియు కంటి సమస్య సాధ్యం. తండ్రితో మంచి సంబంధం, సామాజిక గౌరవ అభివృద్ధి.',
    'ಚಂದ್ರ': 'శుక్ర-చంద్ర భుక్తిలో సౌందర్య ప్రేమ, కళా సృజనాత్మకత మరియు భావోద్వేగ సంతృప్తి లభిస్తుంది. వస్త్ర-ఆభరణ-సుగంధ లాభం, స్త్రీల నుండి అనుకూలత మరియు గృహ సుఖం. కఫ రోగం, శీత సమస్య సాధ్యం కానీ మొత్తం మీద ఆరోగ్యం బాగు. దాంపత్య సుఖం, తల్లి ఆశీర్వాదం మరియు కుటుంబ సామరస్యం.',
    'ಕುಜ': 'శుక్ర-కుజ భుక్తిలో భూమి-వాహన లాభం మరియు భోగ సుఖం లభిస్తుంది. కానీ దాంపత్యంలో కలహం, అతి కామ వాంఛ మరియు భావోద్వేగ ఘర్షణ సాధ్యం. జననేంద్రియ సమస్య, రక్త దోషం మరియు చర్మ రోగం. ఆస్తి వివాదం ఉండవచ్చు, పోటీలలో విజయం సాధ్యం.',
    'ರಾಹು': 'శుక్ర-రాహు భుక్తిలో విదేశ సంబంధం, అంతర్జాతీయ వివాహం మరియు అనిరీక్షిత సంపద సాధ్యం. భోగ-విలాసంలో అతిరేకం, మోసం మరియు అనైతిక సంబంధాల భయం. జననేంద్రియ రోగం, విష భయం మరియు చర్మ సమస్య. దాంపత్యంలో గందరగోళం, కానీ విలాస వస్తువుల లాభం.',
    'ಗುರು': 'శుక్ర-గురు భుక్తిలో శ్రేష్ఠ ఫలం, సంపద-సుఖ-గౌరవం లభిస్తుంది. వివాహ యోగం, సంతాన సుఖం, ధార్మిక కార్యం మరియు కళా-సంస్కృతిలో ఉన్నతి. ఆరోగ్యం బాగుంటుంది, కొవ్వు వృద్ధి సాధ్యం. గురు కృప, సామాజిక ప్రతిష్ఠ మరియు ధర్మ-కర్మలలో పురోగతి.',
    'ಶನಿ': 'శుక్ర-శని భుక్తిలో విలాస వస్తువుల లాభం మరియు స్థిర సంపద లభించవచ్చు. కానీ దాంపత్యంలో శీతలత, భావోద్వేగ దూరం మరియు ఆలస్యం సాధ్యం. మధుమేహం, జననేంద్రియ సమస్య మరియు వాత రోగం. కళా రంగంలో కఠిన పరిశ్రమ తర్వాత విజయం.',
    'ಬುಧ': 'శుక్ర-బుధ భుక్తిలో వ్యాపార-కళా-సంగీతంలో లాభం మరియు సంభాషణ నైపుణ్యం పెరుగుతుంది. రచన, మీడియా మరియు సౌందర్య వ్యాపారంలో పురోగతి సాధ్యం. చర్మ రోగం, అలర్జీ సాధ్యం కానీ మొత్తం మీద ఆరోగ్యం బాగు. మిత్ర-బంధు సహకారం మరియు సామాజిక జీవితంలో ఆనందం.',
    'ಕೇತು': 'శుక్ర-కేతు భుక్తిలో భోగ-విలాసంలో ఆటంకం మరియు వైరాగ్య భావన వస్తుంది. వాహన నష్టం, ఆభరణం పోగొట్టుకోవడం మరియు సంపద హఠాత్ నష్టం సాధ్యం. జననేంద్రియ సమస్య, అస్పష్ట రోగం మరియు అలర్జీ. దాంపత్యంలో అశాంతి, కానీ ఆధ్యాత్మిక ఆసక్తి పెరుగుతుంది.',
  },
};
